// Generated by scaffold-html-to-react-page (deterministic design transpile) from html/frontend/22-alerts.html
// Structure + styling are faithful to the proto. DATA WIRING (fetch/list/handlers) is layered on after.
import { useState } from 'react';
import { Bell, FileText, LayoutDashboard, Settings, Target, Timer, TrendingUp } from 'lucide-react';
import { useScreenQuery } from '~/hooks/useScreenQuery';
import { useAppSelector } from '~/hooks/useAppSelector';
import { get, post } from '~/services/httpMethods';
import type { ParentAlert } from '~/types/view-models';
import '~/styles/protos/alerts.css';

const SHOWN_TITLES = ['ইংরেজিতে দুর্বলতা', 'স্ক্রিন টাইম শেষ', '১ম সাময়িক পরীক্ষা'];

export default function AlertsPage() {
  const sessionUser = useAppSelector((s) => s.auth.user);
  const { data } = useScreenQuery("GET /api/notifications");
  const [allRead, setAllRead] = useState(false);
  const [marking, setMarking] = useState(false);
  const [extra, setExtra] = useState<ParentAlert[]>([]);
  const [moreState, setMoreState] = useState<'idle' | 'loading' | 'done'>('idle');

  const markAllRead = async () => {
    if (allRead || marking) return;
    setMarking(true);
    try {
      await post('/notifications/read-all', {});
      setAllRead(true);
    } finally {
      setMarking(false);
    }
  };

  const loadMore = async () => {
    if (moreState === 'loading') return;
    setMoreState('loading');
    try {
      const dashboard = await get<{ alerts?: ParentAlert[] }>('/parent/dashboard');
      const seen = new Set([...SHOWN_TITLES, ...extra.map((a) => a.titleBn ?? a.title ?? '')]);
      const next = (dashboard.alerts ?? [])
        .filter((a) => !seen.has(a.titleBn ?? a.title ?? ''))
        .slice(0, 10);
      if (next.length === 0) {
        setMoreState('done');
        return;
      }
      setExtra((prev) => [...prev, ...next]);
      setMoreState('idle');
    } catch {
      setMoreState('done');
    }
  };

  return (
    <div data-testid="alerts-page">
      <span className="sr-only" data-testid="screen-data-status">{data ? 'synced' : 'loading'}<span className="sr-only" data-testid="session-user">{sessionUser?.email ?? ''}</span></span>
      <header className="ksr-appbar" >
          <span className="ksr-wordmark" data-testid="appbar-brand">স্মার্টবিদ্যা</span>
          <span className="ksr-appbar-title" data-slot="title" data-testid="sub-title"></span>
          <div className="row" style={{ marginLeft: 'auto' }}>
            <button className="ksr-round" type="button" style={{ position: 'relative' }} data-testid="appbar-notifications" aria-label={allRead ? 'নোটিফিকেশন — নতুন নেই' : 'নোটিফিকেশন — 3 টি না পড়া'}>
              <Bell  />
              {allRead ? null : <span data-testid="appbar-unread" style={{ position: 'absolute', top: '2px', right: '2px', minWidth: '18px', height: '18px', padding: '0 4px', background: 'var(--c-error)', color: 'var(--c-on-primary)', borderRadius: 'var(--radius-pill)', fontSize: 'var(--t-caption-size)', lineHeight: '18px', textAlign: 'center' }}>3</span>}
            </button>
            <button className="ksr-round" type="button" data-testid="appbar-profile" aria-label="প্রোফাইল">
              <span className="avatar" aria-hidden="true">ম</span>
            </button>
          </div>
        </header>
      
        <main className="ksr-main sf-alerts" >
      
          <div>
            <div className="row">
              <p className="t-title-lg ksr-grow" data-testid="al-heading">অ্যালার্ট</p>
              <span className="ksr-badge" data-testid="al-unread">{allRead ? '০ টি নতুন' : '৩ টি নতুন'}</span>
            </div>
            <p className="t-body-sm t-muted" style={{ marginTop: 'var(--space-xxs)' }} data-testid="al-sub">শেষ ৭ দিন · ১২ টি বার্তা</p>
          </div>
      
          
          <div className="row" style={{ flexWrap: 'wrap' }} role="group" aria-label="বার্তার ধরন">
            <button className="ksr-chip is-on" type="button" aria-pressed="true" data-testid="al-filter-all">সব</button>
            <button className="ksr-chip" type="button" aria-pressed="false" data-testid="al-filter-result">ফলাফল</button>
            <button className="ksr-chip" type="button" aria-pressed="false" data-testid="al-filter-weakness">দুর্বলতা</button>
            <button className="ksr-chip" type="button" aria-pressed="false" data-testid="al-filter-payment">পেমেন্ট</button>
            <button className="ksr-chip" type="button" aria-pressed="false" data-testid="al-filter-other">অন্যান্য</button>
          </div>
      
          <button className="ksr-btn is-quiet is-block" type="button" disabled={allRead || marking} onClick={markAllRead} data-testid="al-markall">
            সব পড়া হয়েছে
          </button>
      
          
          <section className="ksr-panel" data-component="list" aria-labelledby="al-list-label">
            <p className="t-body-sm t-semibold" id="al-list-label" data-testid="al-list-label">বার্তা</p>
            <ul className="ksr-list" style={{ marginTop: 'var(--space-sm)' }}>
              <li className="ksr-item" style={{ alignItems: 'flex-start' }} data-testid="al-item">
                <span className="ksr-play is-quiet" aria-hidden="true"><Target  /></span>
                <span className="ksr-col ksr-grow">
                  <span className="row" style={{ gap: 'var(--space-sm)' }}>
                    <span className="t-body-sm t-semibold" data-testid="al-title">ইংরেজিতে দুর্বলতা</span>
                    <span className="ksr-badge is-warn" data-testid="al-badge">দুর্বলতা</span>
                    {allRead ? null : <span data-testid="al-unread-dot" aria-hidden="true" style={{ width: '8px', height: '8px', borderRadius: 'var(--radius-pill)', background: 'var(--c-primary)', flexShrink: '0', marginLeft: 'auto' }}></span>}
                  </span>
                  <span className="t-caption" data-testid="al-body">বাক্য গঠনে ২ বার ভুল · রিমিডিয়াল পাঠ সুপারিশ করা হয়েছে</span>
                  <span className="t-caption" data-testid="al-meta">আজ · রাফিদ</span>
                </span>
              </li>
              <li className="ksr-item" style={{ alignItems: 'flex-start' }} data-testid="al-item">
                <span className="ksr-play is-quiet" aria-hidden="true"><Timer  /></span>
                <span className="ksr-col ksr-grow">
                  <span className="row" style={{ gap: 'var(--space-sm)' }}>
                    <span className="t-body-sm t-semibold" data-testid="al-title">স্ক্রিন টাইম শেষ</span>
                    <span className="ksr-badge is-quiet" data-testid="al-badge">অন্যান্য</span>
                    {allRead ? null : <span data-testid="al-unread-dot" aria-hidden="true" style={{ width: '8px', height: '8px', borderRadius: 'var(--radius-pill)', background: 'var(--c-primary)', flexShrink: '0', marginLeft: 'auto' }}></span>}
                  </span>
                  <span className="t-caption" data-testid="al-body">বৃহস্পতিবার ৬০ মিনিট পূর্ণ হয়েছে</span>
                  <span className="t-caption" data-testid="al-meta">১৫ অক্টোবর · রাফিদ</span>
                </span>
              </li>
              <li className="ksr-item" style={{ alignItems: 'flex-start' }} data-testid="al-item">
                <span className="ksr-play is-quiet" aria-hidden="true"><FileText  /></span>
                <span className="ksr-col ksr-grow">
                  <span className="row" style={{ gap: 'var(--space-sm)' }}>
                    <span className="t-body-sm t-semibold" data-testid="al-title">১ম সাময়িক পরীক্ষা</span>
                    <span className="ksr-badge" data-testid="al-badge">ফলাফল</span>
                    {allRead ? null : <span data-testid="al-unread-dot" aria-hidden="true" style={{ width: '8px', height: '8px', borderRadius: 'var(--radius-pill)', background: 'var(--c-primary)', flexShrink: '0', marginLeft: 'auto' }}></span>}
                  </span>
                  <span className="t-caption" data-testid="al-body">১০–১৬ অক্টোবর · ফলাফল প্রকাশিত</span>
                  <span className="t-caption" data-testid="al-meta">১৪ অক্টোবর · সকল সন্তান</span>
                </span>
              </li>
              {extra.map((alert) => (
                <li key={alert.id} className="ksr-item" style={{ alignItems: 'flex-start' }} data-testid="al-item">
                  <span className="ksr-play is-quiet" aria-hidden="true"><Bell  /></span>
                  <span className="ksr-col ksr-grow">
                    <span className="row" style={{ gap: 'var(--space-sm)' }}>
                      <span className="t-body-sm t-semibold" data-testid="al-title">{alert.titleBn || alert.title}</span>
                      <span className="ksr-badge is-quiet" data-testid="al-badge">অন্যান্য</span>
                    </span>
                    <span className="t-caption" data-testid="al-body">{alert.bodyBn || alert.body}</span>
                  </span>
                </li>
              ))}
            </ul>
          </section>
      
          {moreState === 'done' ? (
            <p className="t-caption" role="status" style={{ textAlign: 'center' }} data-testid="al-end">
              আর কোনো বার্তা নেই।
            </p>
          ) : (
            <button className="ksr-btn is-quiet is-block" type="button" disabled={moreState === 'loading'} onClick={loadMore} data-testid="al-more">
              {moreState === 'loading' ? 'লোড হচ্ছে…' : 'আরও দেখুন'}
            </button>
          )}
      
        </main>
      
        <nav className="ksr-tabbar" aria-label="প্রধান নেভিগেশন">
          <a className="ksr-tab" href="/parent" data-testid="nav-dashboard">
            <LayoutDashboard  />
            ড্যাশবোর্ড
          </a>
          <a className="ksr-tab" href="/parent/progress" data-testid="nav-progress">
            <TrendingUp  />
            অগ্রগতি
          </a>
          <a className="ksr-tab" href="/parent/screen-time" data-testid="nav-screentime">
            <Timer  />
            স্ক্রিন টাইম
          </a>
          <a className="ksr-tab" href="/parent/alerts" data-testid="nav-alerts" aria-current="page">
            <Bell  />
            অ্যালার্ট
          </a>
          <a className="ksr-tab" href="/parent/settings" data-testid="nav-settings">
            <Settings  />
            সেটিংস
          </a>
        </nav>
    </div>
  );
}
